 for(let i=0;i<products.length;i++){const [sku,name,price]=products[i];await c.ui('article'+i,{pageName:'articles',open:"openEditor('article')",form:'#editor-form',route:'articles',fields:{'[name=sku]':'D-'+sku,'[name=name]':name,'[name=price]':price,'[name=unit]':i===24||i===25||i===27?'tim':i===26?'mån':'st','[name=vat]':i===22?'6':i===28?'12':i===29?'0':'25'}});}
