 for(let i=0;i<suppliers.length;i++)await c.ui('supplier'+i,{pageName:'purchases',open:"purchaseOpen('supplier')",form:'#purchase-form',route:'purchases/suppliers',fields:{'[name=name]':suppliers[i],'[name=contact]':'DEMO Leverantörskontakt '+(i+1),'[name=email]':'lev'+(i+1)+'@leverantorer.invalid','[name=address]':'Leverantörens demoadress '+(i+1),'[name=postal]':'00000','[name=city]':'Demostad','[name=terms]':'30','[name=notes]':DEMO}});
 const people=[['Alva','Björk','VD / konsult','Ledning',46000],['Elias','Myr','Ekonomiansvarig','Administration',38500],['Mira','Ekdal','Projektledare','Konsult',41500],['Noah','Lind','Tekniker','Service',34000],['Lova','Gran','Säljare','Försäljning',32500],['Olle','Hed','Lageransvarig','Lager',31000],['Saga','Bäck','Konsult','Konsult',39000],['Nils','Dahl','Supporttekniker','Service',32000],['Freja','Alm','Timanställd','Lager',210],['Arvid','Löv','Timanställd','Service',240],['Idun','Asp','Administratör, deltid','Administration',30000],['Vilgot','Vide','Tidigare medarbetare','Service',29000]];
 for(let i=0;i<people.length;i++){const [first,last,role,department,salary]=people[i],prefix='190001'+String(61+i).padStart(2,'0')+'00'+(i%10),digits=prefix.slice(2).split('').map(Number),sum=digits.reduce((n,x,j)=>{const v=x*(j%2?1:2);return n+Math.floor(v/10)+v%10;},0),personId=prefix+(10-sum%10)%10;
 await c.ui('employee'+i,{pageName:'payroll',open:"hrOpen('employee')",form:'#hr-form',route:'employees',fields:{'[name=firstName]':first,'[name=lastName]':last+' (DEMO)','[name=personId]':personId,'[name=email]':'person'+(i+1)+'@personal.invalid','[name=role]':role,'[name=department]':department,'[name=startDate]':i<4?'2025-01-01':'2026-01-01','[name=salaryType]':i===8||i===9?'hourly':'monthly','[name=salary]':salary,'[name=employmentPercent]':i===10?'50':'100','[name=weeklyHours]':'40','[name=vacationYear]':'2026','[name=vacationDays]':'25','[name=notes]':DEMO+' Syntetiskt samordningsnummer med födelseår 1900. Inte en verifierad identitet.'}});
 }
 await c.once('archived-employee',async()=>{const s=await c.read(),p=s.employees.find(p=>p.id===c.memo.employee11.id);return c.command('employees',{...employeeInput(p),archived:true,endDate:'2026-06-30'});});
 // Initial badges are generated in the browser; these are not photographs or real people.
 for(let i=0;i<2;i++)await c.once('photo'+i,async()=>{const photo=await c.page.evaluate(({initials,color})=>{const canvas=document.createElement('canvas');canvas.width=256;canvas.height=256;const g=canvas.getContext('2d');g.fillStyle=color;g.fillRect(0,0,256,256);g.fillStyle='#fff';g.font='bold 90px sans-serif';g.textAlign='center';g.fillText(initials,128,145);g.font='20px sans-serif';g.fillText('DEMO',128,210);return canvas.toDataURL('image/png');},{initials:i?'EM':'AB',color:i?'#235d90':'#26745a'}),s=await c.read(),p=s.employees.find(p=>p.id===c.memo['employee'+i].id);await c.page.evaluate(id=>{page='payroll';render();hrOpen('employee',id);},p.id);await c.page.locator('#hr-photo-file').setInputFiles({name:'DEMO-'+i+'.png',mimeType:'image/png',buffer:Buffer.from(photo.split(',')[1],'base64')});await expect(c.page.locator('#hr-form [type=submit]')).toBeEnabled();const response=c.page.waitForResponse(r=>r.url().endsWith('/api/employees'));await c.page.locator('#hr-form [type=submit]').click();const r=await response;assert.equal(r.status(),200);await expect(c.page.locator('#hr-form')).toHaveCount(0);return r.json();});
 c.memo.catalog=products;c.memo.people=people;c.save();console.log('Registers ready: 10 customers, 30 products, 8 suppliers, 12 employees.');
