main().catch(e=>{console.error(e);process.exitCode=1});
function employeeInput(p){return {...p,...Object.fromEntries(['salary','employmentPercent','weeklyHours','vacationDays'].map(k=>[k,money(p[k])]))};}
async function journal(c,key,yearId,date,description,lines){const v=await c.call(key+'-draft','accounting/vouchers',{yearId,date,description:'DEMO '+description,reference:'DEMO-UNDERLAG '+key,lines});const s=await c.read(),stored=s.accounting.vouchers.find(x=>x.id===v.id);return c.call(key+'-post','accounting/post',{id:v.id,revision:stored.revision});}
async function issue(c,key,invoiceId,yearId){return c.once(key,async()=>{const s=await c.read(),d=s.invoices.find(d=>d.id===invoiceId);assert.ok(d,key+' missing draft');return c.command('sales/issue',{draftId:d.id,draftUpdated:d.updated,expectedNumber:s.sales.nextNumber,yearId,reviewed:true,paymentInstructions:'DEMO - ingen verklig betalning ska göras.',zeroReason:d.lines.some(l=>l.vat===0)?'DEMO - beräkningsfall, inte en momsrättslig bedömning.':''});});}
async function sale(c,key,{customer=0,date,net,description,yearId,currency='SEK',rate,lines,paid=0,bankAmount,payDate}){const draft=await c.call(key+'-draft','invoices',{customerId:c.memo['customer'+customer].id,date,due:addDays(date,30),currency,...(rate?{exchangeRate:String(rate),rateDate:date,rateSource:'DEMO manuellt vald övningskurs'}:{}),lines:lines||[{description:'DEMO '+description,quantity:'1',price:String(net),unit:'st',vat:25}],note:DEMO});const d=await issue(c,key+'-issue',draft.id,yearId);if(paid)await salesPay(c,key+'-payment',d.id,yearId,payDate||addDays(date,20),paid,bankAmount);return d;}
async function salesPay(c,key,id,yearId,date,amount,bankAmount){return c.once(key,async()=>{const d=(await c.read()).sales.documents.find(d=>d.id===id);return c.command('sales/payments',{id,revision:d.revision,yearId,date,amount:String(amount),...(bankAmount!==undefined?{bankAmount:String(bankAmount)}:{}),bank:'1930',reference:'DEMO simulerad bankbetalning '+key,reviewed:true});});}
async function bill(c,key,{supplier=0,date,yearId,lines,paid=0,payDate,originalId,type='invoice',orderId,leaveDraft=false}){const net=lines.reduce((n,l)=>n+Math.round(Number(l.quantity)*Number(l.price)*100),0),tax=lines.reduce((n,l)=>n+Math.round(Math.round(Number(l.quantity)*Number(l.price)*100)*Number(l.vat)/100),0),d=await c.call(key+'-draft','purchases/invoices',{supplierId:c.memo['supplier'+supplier].id,date,due:addDays(date,30),invoiceNo:'DEMO-'+key,reference:'DEMO PDF-underlag '+key,paymentReference:'DEMO '+key,documentTotal:money(net+tax),lines:lines.map(l=>({...l,deductible:'100',expenseAccount:l.expenseAccount||'4000'})),note:DEMO,type,...(originalId?{originalId}:{}),...(orderId?{orderId}:{})});if(leaveDraft)return d;
 await c.once(key+'-approve',async()=>{const r=(await c.read()).purchases.invoices.find(x=>x.id===d.id);return c.command('purchases/invoices/approve',{id:d.id,revision:r.revision,reviewed:true});});await c.once(key+'-post',async()=>{const r=(await c.read()).purchases.invoices.find(x=>x.id===d.id);return c.command('purchases/invoices/post',{id:d.id,revision:r.revision,yearId,date,description:'DEMO '+key,liabilityAccount:'2440',vatAccount:'2641',roundingAccount:'3740',reviewed:true});});if(paid)await purchasePay(c,key+'-payment',d.id,yearId,payDate||addDays(date,20),paid);return d;}
async function purchasePay(c,key,id,yearId,date,amount){return c.once(key,async()=>{const d=(await c.read()).purchases.invoices.find(x=>x.id===id);return c.command('purchases/payments',{id,revision:d.revision,yearId,date,amount:String(amount),bankAccount:'1930',reference:'DEMO simulerad bankbetalning '+key,description:'DEMO '+key,reviewed:true});});}
async function payroll(c,key,{period,date,yearId,people,paid=true,approved=true}){const s=await c.read(),entries=people.map(i=>{const p=s.employees.find(p=>p.id===c.memo['employee'+i].id),hours=p.salaryType==='hourly'?80:0,gross=p.salaryType==='hourly'?p.salary*hours:Math.round(p.salary*p.employmentPercent/10000);return {employeeId:p.id,hours:String(hours),tax:String(Math.round(gross*.24/100)),contribution:money(Math.round(gross*.3142)),taxConfirmed:true,contributionConfirmed:true,taxBasis:'DEMO - förenklade övningsbelopp 24 % skatt och 31,42 % avgift, inte skattetabell eller verkligt löneunderlag.'};}),r=await c.call(key+'-draft','payruns',{period,payDate:date,entries,note:DEMO+' Beloppen är övningsbelopp. Ingen AGI eller bankfil skickas.'});if(!approved)return r;
 await c.once(key+'-approve',async()=>{const p=(await c.read()).payruns.find(p=>p.id===r.id);return c.command('payruns/approve',{id:p.id,revision:p.revision});});
 const base={runId:r.id,yearId,date,description:'DEMO lön '+period,wageAccount:'7010',contributionExpense:'7510',expenseAccount:'5800',taxAccount:'2710',contributionLiability:'2731',receivableAccount:'1610',wagesPayable:'2910',bankAccount:'1930',reviewed:true};await c.call(key+'-accrual','accounting/payroll',base);if(paid){await c.once(key+'-paid',async()=>{const p=(await c.read()).payruns.find(p=>p.id===r.id);return c.command('payruns/paid',{id:p.id,revision:p.revision});});await c.call(key+'-bank','accounting/payroll',{...base,payment:true});}return r;}
