 await bill(c,'2025-rent',{supplier:2,date:'2025-10-02',yearId:y.id,lines:[{description:'DEMO hyra januari-december 2025',quantity:'12',price:'6000',vat:25,expenseAccount:'5010'}],paid:90000});
