 const {createHash}=require('node:crypto'),{zipSync}=require('fflate'),files=fs.readdirSync(OUT).filter(name=>!name.endsWith('.zip')&&!name.endsWith('.sha256')&&name!=='SHA256SUMS.txt').sort(),sums=files.map(name=>createHash('sha256').update(fs.readFileSync(path.join(OUT,name))).digest('hex')+'  '+name).join('\n')+'\n';fs.writeFileSync(path.join(OUT,'SHA256SUMS.txt'),sums);const zip=zipSync(Object.fromEntries([...files,'SHA256SUMS.txt'].map(name=>[name,new Uint8Array(fs.readFileSync(path.join(OUT,name)))])),{level:6}),zipname='Sizzla-3000-Demo-0.28.1.zip';fs.writeFileSync(path.join(OUT,zipname),zip);fs.writeFileSync(path.join(OUT,zipname+'.sha256'),createHash('sha256').update(zip).digest('hex')+'  '+zipname+'\n');console.log('EXPORTED',dbfile,fs.statSync(dbfile).size,'bytes; ZIP',zip.length,'bytes');
